from solution import house_bowling

def test_zeros():
    assert house_bowling([0]*20) == 0

def test_first_strike():
    assert house_bowling([10] + [0]*18) == 10

def test_all_strikes():
    # 10 frames, each one roll; frames1-8: 30 each=240, f9: 20, f10: 10
    assert house_bowling([10]*10) == 270

def test_frame10_spare_no_bonus():
    rolls = [0]*18 + [5, 5]
    assert house_bowling(rolls) == 10

def test_frame10_strike_only_10():
    rolls = [0]*18 + [10]
    assert house_bowling(rolls) == 10

def test_frame9_strike_frame10_open():
    rolls = [0]*16 + [10, 3, 4]
    # f9: 10+3+4=17, f10: 7
    assert house_bowling(rolls) == 24

def test_frame9_spare_frame10_strike():
    rolls = [0]*16 + [5, 5, 10]
    assert house_bowling(rolls) == 30

def test_frame9_strike_frame10_strike():
    rolls = [0]*16 + [10, 10]
    assert house_bowling(rolls) == 30

def test_all_spares():
    # 9 frames of 5,5 followed by 5: each 15 for f1-f9, f10 5,5 =10
    rolls = [5]*20
    assert house_bowling(rolls) == 9*15 + 10

def test_open_frames():
    assert house_bowling([3, 4]*10) == 70
